export function getPostBySlug(slug) {
  return BLOG_POSTS.find((p) => p.slug === slug);
}

export function getRelatedPosts(post) {
  return (post.relatedSlugs || []).map((slug) => getPostBySlug(slug)).filter(Boolean);
}